// Requirements defines model for Requirements.
type Requirements struct {
	// May What this entry's object classes permit, less whatever the entry
	// editor does not offer — see `elsewhere` on an attribute's kind.
	// The editor never authors an access rule, so `olcAccess` is not
	// here even where a class permits it.
	//
	// `must` is not filtered: an attribute a class requires has to be
	// listed as required whatever any editor does with it.
	May  *[]string `json:"may,omitempty"`
	Must *[]string `json:"must,omitempty"`

	// SettableOperational Operational attributes this server says a client may set on an
	// entry: `USAGE directoryOperation` and no `NO-USER-MODIFICATION`.
	//
	// Operational is not the same as read-only, and treating it as such
	// is why an account could not be locked from here — 389 DS keeps
	// `nsAccountLock` itself and still expects you to set it, as OpenLDAP
	// does for a ppolicy `pwdAccountLockedTime`. Only
	// `NO-USER-MODIFICATION` means the directory owns an attribute.
	//
	// These are not in any object class, so they never appear in `must`
	// or `may` and an entry that has never been locked shows no sign that
	// it could be. They are listed separately rather than merged in,
	// because "what this class permits" and "what the server lets you set
	// besides" are different answers to different questions.
	//
	// `dSAOperation` attributes are excluded: `namingContexts` and
	// `supportedControl` are operational and unflagged too, but they
	// belong to the server rather than to an entry. So is anything with
	// `elsewhere` set on its kind — `aci` is operational and settable,
	// and the editor still does not author an access rule.
	SettableOperational *[]string `json:"settableOperational,omitempty"`

	// Structural The single structural class, or empty when it is ambiguous.
	Structural *string `json:"structural,omitempty"`

	// Unknown Object classes on the entry that the schema does not define.
	Unknown *[]string `json:"unknown,omitempty"`
}

